<script setup>import { useForm, router } from '@inertiajs/vue3'; import AdminLayout from '../../../Layouts/AdminLayout.vue'; defineProps({events:Array}); const form=useForm({title_bn:'',title_en:'',event_date:'',location:'',description_bn:'',description_en:''}); const add=()=>form.post('/admin/events',{onSuccess:()=>form.reset()}); const remove=id=>router.delete(`/admin/events/${id}`);</script>
<template><AdminLayout><h1 class="font-serif text-4xl">ইভেন্ট</h1><div class="mt-8 grid gap-8 md:grid-cols-[1fr_1.5fr]"><form @submit.prevent="add" class="rounded-2xl bg-white p-6 space-y-3"><input v-model="form.title_bn" required placeholder="ইভেন্টের নাম" class="field" /><input v-model="form.title_en" required placeholder="English title" class="field" /><input v-model="form.event_date" required type="date" class="field" /><input v-model="form.location" placeholder="স্থান" class="field" /><button class="rounded-full bg-[#1d4843] px-5 py-2.5 text-sm font-semibold text-white">ইভেন্ট যোগ করুন</button></form><div class="rounded-2xl bg-white p-6"><div v-for="event in events" :key="event.id" class="flex justify-between border-b border-[#edf0eb] py-4"><div><b>{{ event.title_bn }}</b><p class="text-sm text-[#87938d]">{{ event.event_date }} · {{ event.location }}</p></div><button @click="remove(event.id)" class="text-sm text-red-600">মুছুন</button></div></div></div></AdminLayout></template><style scoped>.field{width:100%;border:0;border-radius:.5rem;background:#f7f5f0;padding:.75rem 1rem;box-shadow:inset 0 0 0 1px #dfe1d8}</style>
